<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { knowledgeApi } from '../../api/knowledge'; import type { KnowledgeCategory } from '../../types'; import { apiErrorMessage } from '../../utils/errors'; import PageHeading from '../../components/PageHeading.vue'
const route=useRoute();const router=useRouter();const editing=computed(()=>Boolean(route.params.id));const id=route.params.id as string|undefined;const categories=ref<KnowledgeCategory[]>([]);const saving=ref(false);const loading=ref(editing.value);const formRef=ref<FormInstance>();const form=reactive({title:'',categoryId:'',content:'',version:0});const rules:FormRules={title:[{required:true,message:'请输入标题',trigger:'blur'}],categoryId:[{required:true,message:'请选择分类',trigger:'change'}],content:[{required:true,message:'请输入文章内容',trigger:'blur'}]}
onMounted(async()=>{try{categories.value=(await knowledgeApi.categories()).data;if(editing.value&&id){const {data}=await knowledgeApi.article(id);form.title=data.title;form.categoryId=data.categoryId;form.content=data.content||'';form.version=data.version}}catch(e){ElMessage.error(apiErrorMessage(e));router.back()}finally{loading.value=false}})
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{const response=editing.value&&id?await knowledgeApi.updateArticle(id,{title:form.title,content:form.content,categoryId:form.categoryId,expectedVersion:form.version}):await knowledgeApi.createArticle({title:form.title,content:form.content,categoryId:form.categoryId});ElMessage.success(editing.value?'文章已更新':'草稿已创建');await router.replace(`/knowledge/articles/${response.data.id}`)}catch(e){ElMessage.error(apiErrorMessage(e))}finally{saving.value=false}}
</script>
<template><div v-loading="loading" class="article-editor-page"><PageHeading :title="editing?'编辑文章':'新建文章'" description="编写清晰实用、值得团队信赖的操作指南。" /><section class="content-card form-card"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="two-column-form"><el-form-item label="标题" prop="title"><el-input v-model="form.title" size="large" maxlength="200" show-word-limit /></el-form-item><el-form-item label="分类" prop="categoryId"><el-select v-model="form.categoryId" size="large" placeholder="请选择分类"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id" /></el-select></el-form-item></div><el-form-item label="正文" prop="content"><el-input v-model="form.content" type="textarea" :rows="18" maxlength="100000" placeholder="使用纯文本或 Markdown 编写文章…" /></el-form-item><div class="editor-note">系统按原文保存纯文本和 Markdown，不会渲染 HTML。</div><div class="form-actions"><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{ editing?'保存修改':'创建草稿' }}</el-button></div></el-form></section></div></template>
